 const ids=c.suggestedParticipants?.filter(id=>memberIds.includes(id))??[...memberIds],fit=suggestionFit(state,c,ids),why=recommendationReasons(c,state.preferences[actor],origin??state.plan.city);
 return <article className={`suggestion-card ${expanded?'expanded':''}`}><ActivityPhoto place={c} name={c.name} category={c.category} compact={!expanded}/><div className="suggestion-top"><span className={`suggestion-icon ${c.price===0?'free':''}`}><Icon category={c.category}/></span><button className="dismiss" disabled={!canEdit} aria-label={`Dismiss ${c.name}`} onClick={onDismiss}><X size={14}/></button></div><span className="category-label">{c.category}{c.flexible&&` · ${c.location}`}</span><h3>{c.name}</h3><p>{c.evaluation?c.evaluation.reasons.join(' '):c.reason}</p>{c.evaluation&&<p className="suggestion-fit-note">{datetime(c.start,state.plan.timezone)} · {c.evaluation.status==='fits'?'Checks passed for this draft':c.evaluation.issues[0]??'Review before booking'}</p>}{why.length>0&&<details className="recommendation-reasons"><summary>Why this could suit you</summary><ul>{why.map(reason=><li key={reason}>{reason}</li>)}</ul></details>}<PlaceMetadata place={c} point={origin??state.plan.city} originLabel={originLabel}/><div className="suggestion-metadata"><span><Clock size={13}/>{c.flexible?'Choose your visit time':`${fit.minutes} min incl. travel`}</span><strong>{c.price===null?'Cost unknown':c.price===0?'Free':`${dollars(c.price/Math.max(1,ids.length))} / person`}</strong></div><div className="suggestion-bottom"><Pill tone={c.flexible?'neutral':fit.conflict?'red':!fit.known||fit.over.length?'amber':'green'}>{c.evaluation?c.evaluation.status==='fits'?'Fits this day':'Draft · needs checking':c.flexible?'City place':fit.conflict?'Time conflict':!fit.known?'Needs verification':fit.over.length?'Budget review':'Fits this plan'}</Pill><button onClick={onOpen}>{c.flexible?'Choose activity':'Preview'}<Plus size={14}/></button></div></article>;
