function TaskDialog({item,state,actor,act,busy,onClose}:{item:Item;state:State;actor:string;act:any;busy:boolean;onClose:()=>void}){const {members,memberIds,name}=useGroup();const canEdit=useContext(EditingContext);busy=busy||!canEdit;
 const [editing,setEditing]=useState(false),[title,setTitle]=useState(item.name),[owner,setOwner]=useState(item.taskOwner??actor),[due,setDue]=useState(localDateTime(item.start,state.plan.timezone));
 let error='';try{const instant=zonedStart(due,state.plan.timezone);if(instant.slice(0,10)>state.plan.end)error='Choose a task due time on or before the plan ends.';}catch(e){error=(e as Error).message;}
 return <DialogContent><DialogHeader><DialogTitle>{item.name}</DialogTitle><DialogDescription>Preparation task · Assigned to {name(item.taskOwner??actor)}</DialogDescription></DialogHeader>{editing?<><Field label="Task name"><input value={title} onChange={e=>setTitle(e.target.value)} maxLength={180}/></Field><Field label="Assigned to"><Choose label="Task owner" value={owner} onChange={setOwner} options={members.filter(m=>memberIds.includes(m.id)).map(member=>({value:member.id,label:member.name}))}/></Field><Field label={`Due time (${state.plan.timezone})`}><input type="datetime-local" max={`${state.plan.end}T23:59`} value={due} onChange={e=>setDue(e.target.value)}/></Field>{error&&<p className="inline-error">{error}</p>}</>:<p className="muted">Due {datetime(item.start,state.plan.timezone)}</p>}<label className="check-label"><Checkbox disabled={!canEdit||busy} checked={!!item.done} onCheckedChange={done=>act({type:'task',itemId:item.id,done},'Task updated')}/>Mark task complete</label><DependencyReview key={`${item.id}-${item.revision}`} state={state} item={item} actor={actor} busy={busy} canEdit={canEdit} onAction={act}/><DialogFooter>{editing?<><button className="btn" onClick={()=>setEditing(false)}>Cancel edit</button><button className="btn primary" disabled={busy||!!error||!title.trim()} onClick={async()=>{if(await act({type:'task_edit',itemId:item.id,name:title,taskOwner:owner,start:zonedStart(due,state.plan.timezone)},'Task and reminder updated'))setEditing(false);}}>Save task</button></>:<>{canEdit&&<button className="btn" onClick={()=>{setTitle(item.name);setOwner(item.taskOwner??actor);setDue(localDateTime(item.start,state.plan.timezone));setEditing(true);}}>Edit task</button>}<button className="btn" onClick={onClose}>Done</button></>}</DialogFooter></DialogContent>;
}
function NewItemDialog({state,selectedDay,actor,busy,act,onBrowse,onClose,task=false}:{state:State;selectedDay?:string;actor:string;busy:boolean;act:any;onBrowse:()=>void;onClose:()=>void;task?:boolean}){const {currency,step,dollars,moneyInput,parseMoney}=useMoney();const {members,memberIds,name}=useGroup();const canEdit=useContext(EditingContext);busy=busy||!canEdit;
 const [title,setTitle]=useState(''),[category,setCategory]=useState(task?'Preparation':'Activity'),[owner,setOwner]=useState(actor),[location,setLocation]=useState(dayCity(state,selectedDay??state.plan.start).destination),[start,setStart]=useState(`${selectedDay??state.plan.start}T10:00`),[duration,setDuration]=useState(task?'20':'60'),[amount,setAmount]=useState(task?'0':''),[participants,setParticipants]=useState<string[]>(task?[actor]:[...memberIds]);
 const preparation=category==='Preparation',kind=planKind(state.plan);
 const categories=kind==='trip'?['Activity','Meal','Accommodation','Transport','Preparation','Free stop','Practical stop']:['Activity','Meal','Transport','Preparation','Free stop','Practical stop'];
 const zone=preparation?state.plan.timezone:dayCity(state,start.slice(0,10)).timezone;
 let timeError='';try{const chosen=zonedStart(start,zone);if((!preparation&&chosen.slice(0,10)<state.plan.start)||chosen.slice(0,10)>state.plan.end)timeError=preparation?'Choose a task due time on or before the plan ends.':'Choose a time within the plan dates.';}catch(e){timeError=(e as Error).message;}
 function changeCategory(value:string){setCategory(value);if(value==='Preparation')setAmount('0');}
 return <DialogContent className="modal-large activity-dialog"><DialogHeader><DialogTitle>{preparation?'Add a preparation task':'Add an activity'}</DialogTitle><DialogDescription>{preparation?'Assign a task and choose when it needs to be done.':'Choose a place and a time. You can add costs and participants later.'}</DialogDescription></DialogHeader><div className="modal-body">{!preparation&&<button className="btn activity-browse-button" onClick={onBrowse}><Search size={17}/>Find a place in {state.plan.city?.name??state.plan.destination}</button>}<Field label={preparation?'Task name':'Activity name'}><input value={title} onChange={e=>setTitle(e.target.value)} placeholder={preparation?'Order the cake, confirm the guest list…':kind==='event'?'Venue, dinner, entertainment…':'Restaurant, museum, activity…'} maxLength={180}/></Field><div className="form-grid">{preparation?<Field label="Assigned to"><Choose label="Task owner" value={owner} onChange={setOwner} options={members.filter(m=>memberIds.includes(m.id)).map(m=>({value:m.id,label:m.name}))}/></Field>:<Field label="Location"><input value={location} onChange={e=>setLocation(e.target.value)}/></Field>}<Field label={`${preparation?'Due':'Start'} time (${zone})`}><input type="datetime-local" min={preparation?undefined:`${state.plan.start}T00:00`} max={`${state.plan.end}T23:59`} value={start} onChange={e=>setStart(e.target.value)}/></Field></div>{timeError&&<p className="inline-error" role="alert">{timeError}</p>}<details className="activity-options" open={preparation||undefined}><summary>Optional details <span>{duration} min{!preparation&&` · ${participants.length} people`}</span></summary><div className="form-grid"><Field label="Category"><Choose label="Category" value={category} onChange={changeCategory} options={categories.map(v=>({value:v,label:v==='Preparation'?'Preparation task':v}))}/></Field><Field label="Duration in minutes"><input type="number" min="1" max="1440" value={duration} onChange={e=>setDuration(e.target.value)}/></Field>{!preparation&&<Field label={`Total cost (${currency})`} hint="Leave blank if unknown. Enter 0 for a free activity."><input type="number" min="0" step={step} value={amount} onChange={e=>setAmount(e.target.value)} placeholder="Unknown"/></Field>}</div>{!preparation&&<><h3>Who is joining?</h3><PersonChoices selected={participants} onChange={setParticipants}/></>}</details></div><DialogFooter><button className="btn" onClick={onClose}>Cancel</button><button className="btn primary" disabled={busy||!title.trim()||(!preparation&&!participants.length)||!start||!!timeError||!Number.isInteger(Number(duration))||Number(duration)<1||Number(duration)>1440||(!preparation&&amount!==''&&!Number.isSafeInteger(parseMoney(amount)))} onClick={async()=>{if(await act({type:'add_item',name:title,category,location:preparation?'Preparation':location,start:zonedStart(start,zone),duration:Number(duration),price:preparation?0:amount===''?null:parseMoney(amount),participants:preparation?[owner]:participants,taskOwner:preparation?owner:undefined,policy:preparation?'Preparation task; no booking or payment.':undefined},preparation?'Preparation task added':'Activity added for group review'))onClose();}}>{preparation?'Add task':'Add activity'}</button></DialogFooter></DialogContent>;
}
function PreparationTasks({state,busy,act,onItem,onNew}:{state:State;busy:boolean;act:any;onItem:(item:Item)=>void;onNew?:()=>void}){const {members,memberIds,name}=useGroup();const canEdit=useContext(EditingContext);busy=busy||!canEdit;
 const tasks=state.items.filter(item=>item.category==='Preparation'&&item.status!=='cancelled').sort((a,b)=>a.start.localeCompare(b.start));
 return <section className="panel preparation-tasks"><div className="section-top"><h2>Preparation tasks</h2><Pill>{tasks.filter(task=>task.done).length}/{tasks.length} done</Pill></div>{!tasks.length?<p className="muted">Keep track of what needs to be ready.</p>:tasks.map(task=><div className={`preparation-task ${task.done?'done':''}`} key={task.id}><Checkbox disabled={busy} aria-label={`Mark ${task.name} complete`} checked={!!task.done} onCheckedChange={done=>act({type:'task',itemId:task.id,done},'Task updated')}/><button className="preparation-task-open" onClick={()=>onItem(task)}><strong>{task.name}</strong><span>{name(task.taskOwner??'sam')} · {datetime(task.start,state.plan.timezone)}</span></button></div>)}{onNew&&<button className="btn full" disabled={busy} onClick={onNew}><Plus size={16}/>Add preparation task</button>}</section>;
}
function PreviousTrips({state,act,busy,onDelete}:{state:State;act:any;busy:boolean;onDelete:(id:string,name:string)=>void}){const {currency,step,dollars,moneyInput,parseMoney}=useMoney();
 if(!state.archives?.length)return null;
 return <div className="previous-trips"><h2>Your other plans</h2><p className="source-footnote">Open any saved plan to continue planning. Each plan keeps its own schedule and money.</p>{state.archives.map(a=><details className="panel" key={a.id}><summary><strong>{a.workspace.plan.name}</strong><span>{a.workspace.items.length} plan items · {a.workspace.events.length} financial records</span></summary><div className="archive-content"><button className="btn primary" disabled={busy} onClick={()=>act({type:'select_trip',tripId:a.workspace.plan.id},'Plan opened')}>Open plan</button><button className="btn danger" disabled={busy} onClick={()=>onDelete(a.workspace.plan.id!,a.workspace.plan.name)}><Trash2 size={15}/>Delete plan</button><h3>{planType(a.workspace.plan).schedule}</h3>{a.workspace.items.map(i=><div className="booking-row" key={i.id}><div><strong>{i.name}</strong><small>{i.location} · {datetime(i.start,a.workspace.plan.timezone)}</small></div><span>{i.price===null?'Cost unknown':formatMoney(i.price,planCurrency(a.workspace.plan))}</span></div>)}<h3>Financial records</h3>{a.workspace.events.map(e=><div className="booking-row" key={e.id}><div><strong>{e.label}</strong><small>{e.kind} · {e.mode} · {e.status}</small></div><span>{formatMoney(e.amount,planCurrency(a.workspace.plan))}</span></div>)}{a.workspace.receipts.length>0&&<><h3>Receipts</h3>{a.workspace.receipts.map(r=><div className="booking-row" key={r.id}><div><strong>{r.merchant}</strong><small>{r.date} · {r.status}</small></div><span>{formatMoney(r.total,planCurrency(a.workspace.plan))}</span></div>)}</>}</div></details>)}</div>;
}
